contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guessHash) public payable {
        require(address(this).balance >= 1 ether);

        // Initial state: caller has no guess, so settle must revert.
        bool revertedBeforeLock;
        try c.settle() {
            revertedBeforeLock = false;
        } catch {
            revertedBeforeLock = true;
        }

        c.lockInGuess{value: 1 ether}(guessHash);

        // Record the block recorded by lockInGuess and the current block.
        (uint recordedBlock, ) = c.guesses(address(this));

        // Any call after lockInGuess in the same transaction: block.number is the same as
        // the current block, so settle must revert because block.number is not greater than
        // the recorded block (which equals block.number + 1 at lock time).
        bool revertedDuringActiveSameBlock;
        try c.settle() {
            revertedDuringActiveSameBlock = false;
        } catch {
            revertedDuringActiveSameBlock = true;
        }

        // General rule: settle reverts before an active guess is recorded, and also reverts
        // while the guess is still active (block.number <= recordedBlock). It only succeeds
        // once block.number > recordedBlock, which cannot happen in this single transaction.
        assert(revertedBeforeLock && revertedDuringActiveSameBlock);
    }

    receive() external payable {}
}

